<template><view class="page settings-page"><view class="back" @tap="back">‹</view><view class="head"><text class="title">账号设置</text></view><view class="card settings"><view class="setting-row" @tap="changeAvatar"><text>头像</text><view class="row-value"><image v-if="avatar" class="avatar-image" :src="avatar" mode="aspectFill" /><view v-else class="avatar">林</view><text class="chevron">›</text></view></view><view class="setting-row" @tap="changeNickname"><text>昵称</text><view class="row-value"><text class="muted">{{nickname}}</text><text class="chevron">›</text></view></view><view class="setting-row"><text>学校</text><view class="row-value"><text class="muted">安徽理工大学</text><text class="chevron">›</text></view></view><view class="setting-row"><text>专业</text><view class="row-value"><text class="muted">软件工程</text><text class="chevron">›</text></view></view><view class="setting-row" @tap="changePassword"><text>修改密码</text><view class="row-value"><text class="muted">修改登录密码</text><text class="chevron">›</text></view></view><view class="setting-row"><text>隐私与安全</text><text class="chevron">›</text></view></view></view></template>
<script>export default{data(){return{avatar:uni.getStorageSync('user_avatar')||'',nickname:uni.getStorageSync('user_nickname')||'林间漫步者'}},methods:{back(){uni.navigateBack()},changeAvatar(){uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['album','camera'],success:res=>{this.avatar=res.tempFilePaths[0];uni.setStorageSync('user_avatar',this.avatar)}})},changeNickname(){uni.showModal({title:'修改昵称',editable:true,placeholderText:this.nickname,success:res=>{if(res.confirm&&res.content){this.nickname=res.content;uni.setStorageSync('user_nickname',res.content);uni.showToast({title:'昵称已保存',icon:'success'})}}})},changePassword(){uni.showModal({title:'修改密码',editable:true,placeholderText:'请输入新密码',success:res=>{if(res.confirm&&res.content){uni.setStorageSync('user_password',res.content);uni.showToast({title:'密码已更新',icon:'success'})}}})}}}</script>
<style lang="scss">@import '../../common/portal.scss';.settings-page{padding-top:18rpx}.back{display:flex;align-items:center;width:68rpx;height:68rpx;color:#181c1c;font-size:58rpx}.settings-page .head{padding:40rpx 4rpx 42rpx}.settings-page .title{font-size:54rpx}.settings{padding:0;overflow:hidden}.setting-row{display:flex;align-items:center;justify-content:space-between;min-height:110rpx;padding:0 28rpx;border-bottom:1rpx solid #edf1ef;color:#53615f;font-size:28rpx;box-sizing:border-box}.setting-row:last-child{border:0}.row-value{display:flex;align-items:center;gap:10rpx}.avatar,.avatar-image{display:flex;align-items:center;justify-content:center;width:72rpx;height:72rpx;border-radius:50%;background:#d6e6e3;color:#006d37;font-size:28rpx}.avatar-image{display:block}.chevron{color:#8b9890;font-size:34rpx}.muted{font-size:25rpx}</style>
